     notatmaler (prefix, tekster) AS (
    VALUES ('BBh', ARRAY['Gjentatt forhøyet blodtrykk. Starter amlodipin 5 mg, kontroll om fem måneder.',
                         'Blodtrykket fortsatt over mål. Dosen økt til 10 mg, livsstilsråd gitt.',
                         'Noe lavere blodtrykk. Fortsetter dagens behandling.',
                         'Stabilt blodtrykk og god toleranse. Kontroll om seks måneder.']),
           ('IBh', ARRAY['HbA1c over målverdi. Metformin økt, kostholdsveiledning og råd om daglig gange.',
                         'HbA1c fortsatt høy. Tilbud om diabetesskole.',
                         'Litt lavere HbA1c. Fortsetter metformin.',
                         'Vekten går ned. Behandlingen fortsetter uendret.']),
           ('TLh', ARRAY['Astma med nattlige symptomer. Starter inhalasjonssteroid og instruert i inhalasjonsteknikk.',
                         'Færre symptomer. Spirometri omtrent uendret, fortsetter behandlingen.',
                         'Økte plager i pollensesongen. Antihistamin lagt til.',
                         'God kontroll uten akutte forverringer siste halvår.']),
           ('ME', ARRAY['Tretthet og kuldeintoleranse. TSH klart forhøyet, starter levotyroksin 75 mikrogram.',
                        'TSH synkende. Dose økt til 100 mikrogram, ny prøve om seks måneder.',
                        'Mer energi. TSH nær normalt, uendret dose.',
                        'TSH innenfor referanseområdet. Kontroll om seks måneder.']),
           ('SM', ARRAY['Kjent hypertensjon. Redusert eGFR og høyt kreatinin, nyrefunksjon følges tett.',
                        'eGFR lett synkende. Legemidler gjennomgått, unngår NSAID.',
                        'Blodtrykket stiger over mål. Vurderer doseendring, henvisning til nyrelege ved fortsatt fall i eGFR.',
                        'Fortsatt fallende eGFR og blodtrykk over mål. Ny kontroll om fem måneder.']),
           ('OH', ARRAY['Langvarig uro og bekymringer. GAD-7 høy, starter samtaleterapi.',
                        'Noe bedring, sover bedre. Fortsetter samtaleterapi.',
                        'Flere gode dager. Gjennomgang av mestringsstrategier.',
                        'Stabil bedring. Oppfølging hver sjette måned.']),
           ('NA', ARRAY['Helsekontroll barn. Vekst og utvikling i forventet kurve, vaksinestatus gjennomgått.',
                        'Høyde og vekt følger kurven. Ingen bekymringer fra foresatte.',
                        'God trivsel på skolen. Ingen funn ved undersøkelse.']),
           ('KD', ARRAY['Forhøyet totalkolesterol og LDL. Kostholdsråd og trening, starter atorvastatin 20 mg.',
                        'Kolesterol synkende på statin. Ingen bivirkninger.',
                        'Lipidene nærmer seg målverdi. Fortsetter statin.',
                        'Lipidene ved mål. Årlig kontroll videre.']),
           ('ESh', ARRAY['Type 2 diabetes med HbA1c over mål. Metformin økt, nyrefunksjon kontrollert.',
                         'HbA1c stiger. SGLT2-hemmer lagt til, ny kontroll om fem måneder.',
                         'Fortsatt høy HbA1c. Kosthold og medisinbruk gjennomgått.',
                         'eGFR lett synkende, følges videre.']),
           ('HNh', ARRAY['Nedstemthet og lav energi. PHQ-9 høy, starter samtaleterapi og sertralin.',
                         'Delvis effekt. Dosen økt, samtaleterapi fortsetter.',
                         'Bedre stemningsleie og søvn. PHQ-9 synkende.',
                         'Tydelig bedring. Nedtrapping vurderes senere.']),
           ('JSh', ARRAY['Akutte korsryggsmerter uten utstråling. Råd om aktivitet og enkel smertestillende.',
                         'Tilbakevendende plager. Henvist til fysioterapi.',
                         'Bedre med trening. Smerter lavere enn ved forrige kontroll.',
                         'Moderate ryggplager. Fortsetter egentrening.']),
           ('LR', ARRAY['Første svangerskapskontroll. Termin midten av september, rutineprøver tatt.',
                        'Normal fosterlyd og symfysefundusmål. Blodtrykk og urin normalt.',
                        'God trivsel. Hemoglobin lett synkende, råd om jerninntak.',
                        'Ingen plager. Vekt og blodtrykk som forventet.']),
           ('SBh', ARRAY['Forhøyet blodtrykk ved gjentatte målinger. Livsstilsråd og ny kontroll om fem måneder.',
                         'Blodtrykket stiger fortsatt. Hjemmemåling avtalt.',
                         'Vedvarende forhøyet blodtrykk. Oppstart av behandling diskutert.']),
           ('AH', ARRAY['Tretthet og blekhet. Lav hemoglobin og ferritin, starter jerntilskudd.',
                        'Hemoglobin stiger på jern. Fortsetter behandlingen.',
                        'God respons. Ferritin øker, mindre tretthet.',
                        'Hemoglobin normalisert. Fortsetter jern i tre måneder til.']),
           ('PT', ARRAY['Type 2 diabetes med nedsatt nyrefunksjon og hypertensjon. Kontroller etter fast plan.',
                        'eGFR synkende. Metformindose justert etter nyrefunksjon.',
                        'HbA1c litt høyere. Kosthold og legemidler gjennomgått.',
                        'Fortsatt synkende eGFR. Henvisning til nyrelege vurdert.']),
           ('GFh', ARRAY['Diabetes og hypertensjon. HbA1c og blodtrykk over mål, begge legemidler økt.',
                         'Litt bedre verdier. Vektreduksjon anbefalt.',
                         'Vekten går ned og blodtrykket synker.',
                         'Stabile verdier. Fortsetter dagens behandling.']),
           ('RA', ARRAY['Tretthet og vektøkning over ett år. TSH lett forhøyet, kontrolleres på nytt.',
                        'TSH stiger og vekten fortsetter opp. Ny prøve før valg av behandling.',
                        'TSH tydelig forhøyet og vekt økende. Starter levotyroksin ved neste kontroll.']),
           ('KL', ARRAY['Blodtrykk lett forhøyet. Hjemmemåling og livsstilsråd.',
                        'Blodtrykket stiger. Hjemmemålinger bekrefter forhøyede verdier.',
                        'Fortsatt økende blodtrykk. Behandling diskuteres hvis trenden fortsetter.']),
           ('YR', ARRAY['KOLS med hoste og tungpustethet ved anstrengelse. FEV1 redusert, inhalasjonsbehandling justert.',
                        'FEV1 noe lavere. Røykeslutt gjentatt anbefalt, inhalasjon uendret.',
                        'Moderat forverring i vinter. Kur med antibiotika og prednisolon.',
                        'Stabil, men redusert lungefunksjon. Lungerehabilitering vurdert.']),
           ('LH', ARRAY['Nedstemthet og nedsatt energi. PHQ-9 lav til moderat, samtaleoppfølging avtalt.',
                        'Flere symptomer enn sist. PHQ-9 økende.',
                        'Økende symptomer og dårligere søvn. Behandling og henvisning vurderes.']),
           ('MSh', ARRAY['Overvekt med vektøkning siste år. Kostholdsveiledning og råd om aktivitet.',
                         'Vekten stiger fortsatt. Konkrete mål avtalt og tettere oppfølging.',
                         'Små endringer i vekt. Fortsetter oppfølging.']),
           ('HBh', ARRAY['Gjentatt forhøyet blodtrykk. Livsstilsråd og ny kontroll.',
                         'Blodtrykket stiger. Starter amlodipin.',
                         'Fortsatt høyt, dosen økes.']),
           ('TM', ARRAY['Første svangerskapskontroll. Termin midten av desember, rutineprøver tatt.',
                        'Normalt forløp. Fosterlyd god, blodtrykk normalt.',
                        'Ingen plager. Hemoglobin lett synkende.',
                        'God trivsel. Vekt og blodtrykk som forventet.']),
           ('RSh', ARRAY['Dårlig regulert type 2 diabetes. HbA1c over 10, starter kveldsinsulin.',
                         'HbA1c synkende, men fortsatt høy. Opplæring i egenmåling.',
                         'Bedring med kosthold og trening.']),
           ('EL', ARRAY['Nylig diagnostisert type 2 diabetes. Starter metformin og kostholdsveiledning.',
                        'HbA1c stiger. Metformin økt.',
                        'HbA1c fortsatt stigende og vekten øker. Vurderer tillegg av ny medisin.',
                        'HbA1c over mål. Ny samtale om kosthold og aktivitet.']),
           ('SA', ARRAY['Korsryggsmerter uten utstråling. Råd om aktivitet og smertestillende ved behov.',
                        'Bedring, mindre smerter. Fortsetter trening.',
                        'Rolig ryggsituasjon.']),
           ('BO', ARRAY['Kjent hypotyreose, stabil på levotyroksin. TSH normal.',
                        'TSH innenfor referanseområdet. Uendret dose.',
                        'Ingen plager. Fortsetter dagens behandling.']),
           ('LKh', ARRAY['Astma med anstrengelsesutløst hoste. Spirometri tatt, starter inhalasjonssteroid.',
                         'God effekt. Vekst og lungefunksjon følger forventet utvikling.',
                         'Ingen forverring. Inhalasjonsteknikk gjennomgått.',
                         'Fortsatt god kontroll.']),
           ('EKa', ARRAY['Årlig helsekontroll. Normal vekst, ingen plager.']),
           ('EKb', ARRAY['Vrikket ankel under fotball. Stabilt ledd, ingen mistanke om brudd. Støttebandasje og avlastning.']),
           ('EKc', ARRAY['Moderate kviser. Starter lokalbehandling med benzoylperoksid.']),
           ('AVa', ARRAY['Forkjølelse uten tegn til bakteriell infeksjon. Symptomatisk behandling.']),
           ('AVb', ARRAY['Sinusitt med trykk over kinnbena. Avventer antibiotika, nesespray og kontroll ved forverring.']),
           ('AVc', ARRAY['Sår hals og feber. Positiv strep A-test, behandlet med penicillin V.']),
           ('AVd', ARRAY['Vrikket ankel etter fall. Stabilt ledd, ingen brudd. Støttebandasje.']),
           ('AFa', ARRAY['Ukomplisert urinveisinfeksjon. Positiv urinstix, pivmecillinam i tre dager.']),
           ('AFb', ARRAY['Tett nese og trykk i pannen i åtte dager. Saltvannsskylling og nesespray.']),
           ('AFc', ARRAY['Sår hals med feber. Strep A-test positiv, penicillin V i ti dager.']),
           ('AFd', ARRAY['Nytt tilfelle av cystitt. Urinstix positiv, behandlet som sist.']),
           ('TNa', ARRAY['Ønsker å slutte å røyke. Sluttdato avtalt, nikotinerstatning og oppfølging.']),
           ('TNb', ARRAY['Røykfri siden i vår. Vekten har økt litt. Fortsetter støtte.']),
           ('TNc', ARRAY['Hoste i en uke med lett feber. Frie lungelyder, symptomatisk behandling.']),
           ('TNd', ARRAY['Hoste og slim i to uker. Ingen tegn til lungebetennelse, symptomatisk behandling.']),
           ('KLm', ARRAY['Hetetokter og søvnforstyrrelser. Livsstilstiltak og alternativer gjennomgått.']),
           ('LRa', ARRAY['Ønsker prevensjon. Alternativer gjennomgått, starter minipille.']),
           ('LRb', ARRAY['Svie og hyppig vannlating. Urinstix positiv, behandlet med pivmecillinam.']),
           ('LRc', ARRAY['Helsekontroll før planlagt graviditet. Folat anbefalt, ingen funn.']),
           ('TMa', ARRAY['Rutinemessig helsekontroll. Ingen funn.']),
           ('TMb', ARRAY['Migrene med aura, to anfall siste måned. Starter anfallsbehandling.']),
           ('TMc', ARRAY['Ukomplisert cystitt, behandlet med pivmecillinam.']),
           ('SAa', ARRAY['Magesmerter og diaré i to døgn. Antatt viral gastroenteritt, råd om væske.']),
           ('SAb', ARRAY['Forkjølelse med hoste. Symptomatisk behandling.']),
           ('BOa', ARRAY['Smerter i høyre kne ved gange i trapper. Kneartrose, råd om trening og enkel smertestillende.'])),
     notat (key, tekst) AS (
SELECT p.key, n.tekster[CASE WHEN p.seq = 1 OR cardinality(n.tekster) = 1 THEN 1
                              ELSE 2 + (p.seq - 2) % (cardinality(n.tekster) - 1) END]
FROM plan p
         JOIN notatmaler n ON n.prefix = p.prefix
WHERE p.seq % 6 <> 0 OR cardinality(n.tekster) = 1
UNION ALL
SELECT v.key, v.tekst
FROM (VALUES ('BB3', 'Blodtrykk synkende på amlodipin. Fortsetter dagens dose, ny kontroll om tre måneder.'),
             ('IB4', 'HbA1c nær målverdi. Fortsetter metformin og kostholdsråd.'),
             ('JS1', 'Akutte korsryggsmerter uten utstråling. Råd om aktivitet, kontroll ved manglende bedring.'),
             ('HN2', 'Bedring etter oppstart samtaleterapi. Fortsatt sykmeldt 50 prosent.'),
             ('AF1', 'Forkjølelse uten tegn til bakteriell infeksjon. Symptomatisk behandling.'),
             ('LK1', 'God astmakontroll. Videreføres uendret.')) AS v (key, tekst)),
